import React, { forwardRef, useEffect, useImperativeHandle, useRef } from 'react';
import { omit } from 'lodash';
import { translate } from '@fiverr-private/i18n-react';
import { usePopoverContext } from '@fiverr-private/popover';
import { Box, placeholderStyles } from '@fiverr-private/theme';
import { Typography } from '@fiverr-private/typography';
import { ChevronButton } from '@fiverr-private/button';
import { SELECT_ROLE } from '../constants';
import { useSelectedLabelContent } from '../useSelectedLabelContent';
import { getValidationStylingProps } from '../../shared/style';
import { SelectTriggerProps } from './types';

const Trigger = forwardRef<HTMLDivElement, SelectTriggerProps>(
  (
    {
      placeholder,
      name,
      isSuccess,
      isError,
      disabled,
      size,
      hideChevron,
      fullWidth,
      options,
      selectedValues,
      width = 'fit-content',
      isMultiSelect,
      autoFocus,
      copies = {
        itemsSelectedText: (count) => translate('forms.select.itemsSelected', { params: { count } }),
      },
      selectedItemRenderer,
      'aria-expanded': ariaExpanded,
      'aria-haspopup': ariaHasPopup,
      theme,
      dataTrackTag,
      dataTrackValue,
    },
    ref
  ) => {
    const internalRef = useRef<HTMLDivElement>(null);
    const { open } = usePopoverContext();
    const selectedLabelContent = useSelectedLabelContent(
      selectedValues,
      options,
      copies,
      selectedItemRenderer,
      isMultiSelect
    );
    const showPlaceHolder = !selectedLabelContent && placeholder;
    const selectPlaceholderStyles = omit(placeholderStyles, ['fontSize', 'lineHeight']);
    const triggerWidth = fullWidth ? '100%' : width;
    const isLarge = size === 'lg';
    const isDark = theme === 'dark';
    useImperativeHandle(ref, () => internalRef.current!);
    useEffect(() => {
      if (autoFocus && internalRef.current) {
        internalRef.current.focus();
      }
    }, [autoFocus]);

    return (
      <Box
        title={name}
        position="relative"
        width={triggerWidth}
        borderRadius="lg"
        borderWidth="sm"
        cursor="pointer"
        borderStyle="solid"
        {...getValidationStylingProps({ isError, isSuccess, disabled, open })}
        tabIndex={disabled ? -1 : 0}
        ref={internalRef}
        aria-expanded={ariaExpanded}
        aria-haspopup={ariaHasPopup}
        {...(isDark ? { borderColor: 'white_20', backgroundColor: 'white_10' } : undefined)}
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
      >
        <Box
          cursor="pointer"
          color="inherit"
          position="relative"
          boxSizing="borderBox"
          display="flex"
          alignItems="center"
          userSelect="none"
          lineHeight={isLarge ? 'b_lg' : 'b_md'}
          fontSize="b_md"
          paddingY={isLarge ? '2.5' : '2'}
          paddingX="3"
          width={triggerWidth}
          justifyContent={fullWidth ? 'spaceBetween' : undefined}
          role={SELECT_ROLE}
        >
          <Typography
            paddingRight={hideChevron ? '0' : '2'}
            {...(showPlaceHolder ? { ...selectPlaceholderStyles } : { color: isDark ? 'grey_300' : undefined })}
            overflow="hidden"
            textOverflow="ellipsis"
            whiteSpace="nowrap"
          >
            {showPlaceHolder ? placeholder : selectedLabelContent}
          </Typography>
          {!hideChevron && (
            <ChevronButton
              disabled={disabled}
              size="3xs"
              chevronDirection={open ? 'up' : undefined}
              theme={isDark ? 'light' : 'dark'}
            />
          )}
        </Box>
      </Box>
    );
  }
);

Trigger.displayName = 'Trigger';

export default Trigger;
